"""Behavioral tests for the in-memory publication and adoption registry.

These tests encode the release contract in docs/contract.md: publication records
which version identifiers are available, and adoption moves one existing usage to
one already-published version without changing local usage configuration.
"""

import copy
import pathlib
import sys
import unittest


PROJECT_ROOT = pathlib.Path(__file__).resolve().parents[1]
sys.path.insert(0, str(PROJECT_ROOT / "src"))

from registry import adopt, publish  # noqa: E402


class RegistryContractTest(unittest.TestCase):
    """Contract examples for pinned version publication and explicit adoption."""

    def test_publish_adds_version_identifier_to_versions_set(self):
        """Publishing makes a version adoptable without touching any usages."""
        versions = {"v1"}

        publish(versions, "v2")

        self.assertEqual({"v1", "v2"}, versions)

    def test_adopt_updates_only_the_selected_version_for_existing_usage(self):
        """Adoption preserves retry configuration and unrelated usages."""
        versions = {"v1", "v2"}
        usages = {
            "tile:dashboard": {"version": "v1", "retry_limit": 1},
            "job:nightly": {"version": "v1", "retry_limit": 5},
        }

        adopt(usages, "tile:dashboard", "v2", versions)

        self.assertEqual(
            {
                "tile:dashboard": {"version": "v2", "retry_limit": 1},
                "job:nightly": {"version": "v1", "retry_limit": 5},
            },
            usages,
        )

    def test_adopt_rejects_unknown_usage_before_mutating(self):
        """An adoption target must already exist as a usage binding."""
        versions = {"v1", "v2"}
        usages = {"tile:dashboard": {"version": "v1", "retry_limit": 1}}
        before = copy.deepcopy(usages)

        with self.assertRaises(ValueError):
            adopt(usages, "job:nightly", "v2", versions)

        self.assertEqual(before, usages)

    def test_adopt_rejects_unpublished_version_before_mutating(self):
        """A usage can adopt only a version that has already been published."""
        versions = {"v1"}
        usages = {"tile:dashboard": {"version": "v1", "retry_limit": 1}}
        before = copy.deepcopy(usages)

        with self.assertRaises(ValueError):
            adopt(usages, "tile:dashboard", "v2", versions)

        self.assertEqual(before, usages)


if __name__ == "__main__":
    unittest.main()

